pub(super) struct Codebook {
    width: usize,
    values: &'static [i8],
    bits: usize,
    packed: &'static [u8],
}

impl Codebook {
    pub(super) fn row(self, index: usize) -> [f32; 8] {
        let mut output = [0.0; 8];
        for (column, slot) in output[..self.width].iter_mut().enumerate() {
            let element = index * self.width + column;
            let per_byte = 8 / self.bits;
            let code = (self.packed[element / per_byte] >> ((element % per_byte) * self.bits))
                & ((1 << self.bits) - 1);
            *slot = self.values[code as usize] as f32;
        }
        output
    }
}

